class Solution {
  private int[] digits;
  private long[][][][][] memo;

  // returns {count, waviness sum} of completions
  private long[] dfs(int pos, int d1, int d2, boolean tight, boolean started) {
    if (pos == digits.length) return new long[] {1, 0};
    int s = started ? 1 : 0;
    if (!tight && memo[pos][d1][d2][s] != null) return memo[pos][d1][d2][s];
    int limit = tight ? digits[pos] : 9;
    long count = 0, wave = 0;
    for (int d = 0; d <= limit; d++) {
      boolean st = started || d != 0;
      int n1 = st ? d : 10, n2 = st ? d1 : 10;
      long add = 0;
      if (started && d1 != 10 && d2 != 10) {
        if ((d1 > d2 && d1 > d) || (d1 < d2 && d1 < d)) add = 1;
      }
      long[] sub = dfs(pos + 1, n1, n2, tight && d == limit, st);
      count += sub[0];
      wave += sub[1] + add * sub[0];
    }
    long[] res = {count, wave};
    if (!tight) memo[pos][d1][d2][s] = res;
    return res;
  }

  private long total(long n) {
    if (n <= 0) return 0;
    String str = Long.toString(n);
    digits = new int[str.length()];
    for (int i = 0; i < digits.length; i++) digits[i] = str.charAt(i) - '0';
    memo = new long[digits.length][11][11][2][];
    return dfs(0, 10, 10, true, false)[1];
  }

  public long totalWaviness(long num1, long num2) {
    return total(num2) - total(num1 - 1);
  }
}
